import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {readFileSync,existsSync,mkdirSync,writeFileSync} from 'node:fs';
import {resolve,dirname,extname} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const {checkout}=JSON.parse(readFileSync(resolve(root,'.work/source.json'),'utf8'));
const {chromium}=await import(pathToFileURL(resolve(checkout,'apps/web/node_modules/playwright/index.mjs')).href);
const directory=resolve(root,process.env.CONVERSATION_BUNDLE??'.work/services');
const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.wasm':'application/wasm','.woff2':'font/woff2','.svg':'image/svg+xml','.json':'application/json'};
const server=createServer((request,response)=>{const path=resolve(directory,'.'+decodeURIComponent(new URL(request.url,'http://localhost').pathname));if(!path.startsWith(directory+'/')){response.writeHead(403);response.end();return;}if(!existsSync(path)){response.writeHead(404);response.end();return;}response.setHeader('Content-Type',mime[extname(path)]??'application/octet-stream');response.end(readFileSync(path));});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const origin=`http://127.0.0.1:${server.address().port}`;
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:900,height:1100}});
const errors=[],network=[],consoleErrors=[];
page.on('pageerror',error=>errors.push(error.message));page.on('console',message=>{if(message.type()==='error')consoleErrors.push(message.text());});
page.on('request',request=>{if(!request.url().startsWith(origin)&&!request.url().startsWith('data:')&&!request.url().startsWith('blob:'))network.push(request.url());});
page.on('websocket',socket=>network.push(socket.url()));
await page.addInitScript(()=>{window.__bridge=[];window.webkit={messageHandlers:{tabConversation:{postMessage(message){window.__bridge.push(message);if(message.type!=='action')return;let reply={requestId:message.requestId,ok:true,result:{entries:[{kind:'file',mimeType:'text/x-swift',byteLength:1536}]}};if(message.action.kind!=='filesystemMetadata')reply={requestId:message.requestId,ok:false,error:'Unexpected metadata action '+message.action.kind};queueMicrotask(()=>window.TabConversation.resolve(reply));}}}};});
const base={bridgeVersion:1,sessionId:'session',projectId:'project',environmentId:'project',connectionState:'live',revision:1,theme:'light',cwd:'/workspace',status:'idle',turns:[],items:[{id:'answer',kind:'assistant',text:'[Source file](/workspace/src/main.swift)',isComplete:true}],messages:[],font:{interfaceSize:16,promptSize:14,codeSize:13},capabilities:{nativeActions:true,filesystem:true}};
const checks=[];
try{
 await page.goto(origin+'/index.html',{waitUntil:'networkidle'});await page.waitForFunction(()=>window.TabConversation);
 await page.evaluate(snapshot=>window.TabConversation.update(snapshot),base);
 await page.getByText('Source file',{exact:true}).waitFor();
 await page.getByText('main.swift',{exact:true}).hover();
 await page.getByText('/workspace/src/main.swift · 2 KB',{exact:true}).waitFor({timeout:10000});
 const actions=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action').map(item=>item.action));
 assert.ok(actions.length>0);assert.ok(actions.every(action=>action.kind==='filesystemMetadata'));
 assert.deepEqual(actions[0],{kind:'filesystemMetadata',environmentId:'project',input:{paths:['/workspace/src/main.swift']}});
 checks.push('actual source workspace tooltip consumes kind/MIME/byteLength from bulk entries[0]');
 await page.mouse.move(850,1000);const before=actions.length;
 await page.evaluate(snapshot=>window.TabConversation.update({...snapshot,revision:2,capabilities:{nativeActions:true,filesystemWrite:true}}),base);
 await page.getByText('main.swift',{exact:true}).hover();
 await page.getByText('/workspace/src/main.swift',{exact:true}).waitFor({timeout:10000});
 assert.equal(await page.getByText('/workspace/src/main.swift · 2 KB',{exact:true}).count(),0);
 assert.equal(await page.evaluate(()=>window.__bridge.filter(item=>item.type==='action').length),before);
 checks.push('write permission does not grant file-metadata read access');
 const diagnostics=await page.evaluate(()=>window.__bridge.filter(item=>item.type==='error'||item.type==='renderDiagnostic'&&item.scope!=='resize-observer'));
 assert.deepEqual(diagnostics,[]);assert.deepEqual(errors,[]);assert.deepEqual(consoleErrors,[]);assert.deepEqual(network,[]);
 const output=resolve(root,'.work/qa/file-metadata');mkdirSync(output,{recursive:true});await page.screenshot({path:resolve(output,'file-metadata.png'),fullPage:true});writeFileSync(resolve(output,'report.json'),JSON.stringify({checks,errors,network,diagnostics},null,2));
 process.stdout.write(JSON.stringify({checks,errors,network,diagnostics},null,2)+'\n');
}finally{await browser.close();server.close();}
